<h2>Vista previa Bayer — <?=e(ucfirst($type))?></h2><form class="row g-2 mb-3" method="get" action="<?=url('/bayer/datos')?>"><input type="hidden" name="type" value="<?=e($type)?>"><div class="col-auto"><input class="form-control" type="date" name="from" value="<?=e($_GET['from']??'')?>"></div><div class="col-auto"><input class="form-control" type="date" name="to" value="<?=e($_GET['to']??'')?>"></div><div class="col-auto"><button class="btn btn-primary">Filtrar</button></div></form><div class="mb-3"><?php foreach(['xlsx'=>'Excel','csv'=>'CSV','json'=>'JSON','txt'=>'TXT','pdf'=>'PDF'] as $f=>$l): ?><a class="btn btn-sm btn-outline-secondary" href="<?=url('/export?type='.urlencode($type).'&format='.$f.'&from='.urlencode($_GET['from']??'').'&to='.urlencode($_GET['to']??''))?>"><?=$l?></a> <?php endforeach;?></div><div class="table-responsive"><table class="table table-sm table-striped"><thead><tr><?php if($rows)foreach(array_keys($rows[0]) as $h): ?><th><?=e($h)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r): ?><tr><?php foreach($r as $v): ?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div>
